. "$PSScriptRoot/PhaseA.FixtureCleanup.Tests.ps1"
$list=New-Object 'System.Collections.Generic.List[object]';try {$null=Invoke-PhaseASetupCreation $list 'root' {throw 'private creation failure'}}catch{}
if($list.Count -ne 1 -or $list[0].result -cne 'UNCONFIRMED'){throw 'ROOT_ATTEMPT_NOT_RETAINED'}
function Run-Early($f,[string]$mode,[string]$failure,[hashtable]$prior=@{}) {
 $modeBox=@{value=$mode};$cleanupAction={param($target) if($modeBox.value -ceq 'FAIL'){throw 'private cleanup error'};if($modeBox.value -ceq 'REMOVE'){Remove-PhaseAFixture $target};if($modeBox.value -ceq 'PARTIAL'){[IO.File]::Delete($target.protectedFile);throw 'partial cleanup failure'}}.GetNewClosure()
 $creation=New-Object 'System.Collections.Generic.List[object]';Invoke-PhaseASetupCreation $creation 'root' {};if($failure -ceq 'PROTECTED'){try{Invoke-PhaseASetupCreation $creation 'protected' {throw 'private setup failure'}}catch{}}elseif($failure -ceq 'ACL'){Invoke-PhaseASetupCreation $creation 'protected' {}}
 $existing=@{marker='earlier-violation'};$backend=@{CleanupObservation={param($f,$phase) Get-PhaseAFixtureCleanupObservation $f $phase 'INJECTED'};Setup={param($accounts,$evidence,$observe,$cleanupObserve) $evidence['earlier']=$existing;foreach($key in $prior.Keys){$evidence[$key]=$prior[$key]};Invoke-PhaseAEarlyFixtureCleanup $f $evidence $creation $true ($failure -ceq 'CHILD') $(if($failure -ceq 'ACL'){'ACL_REJECTED'}elseif($failure -ceq 'CHILD'){'CHILD_UNCONFIRMED'}else{'SETUP_FAILED'}) $cleanupObserve $cleanupAction;if($failure -ceq 'CHILD'){throw 'STAGE2_CHILD_UNCONFIRMED'};if($failure -ceq 'ACL'){throw 'STAGE3_ACL_REJECTED'};throw 'synthetic setup failure'}.GetNewClosure()}
 $accounts=@(@{sid='S-1-5-21-1'},@{sid='S-1-5-21-2'});$sink=@{};$thrown='';$result=$null;try{$result=Invoke-PhaseAStage3 $accounts @() $backend @{} $sink}catch{$thrown=$_.Exception.GetBaseException().Message};return @{sink=$sink;status=$(if($null -eq $result){''}else{$result.status});thrown=$thrown}
}
$f=New-TestFixture;try{$x=Run-Early $f 'REMOVE' 'PROTECTED';$c=$x.sink.evidence.fixtureCleanup;if($c.setupReason -cne 'SETUP_FAILED' -or $c.creation.Count -ne 2 -or $c.creation[1].result -cne 'UNCONFIRMED' -or -not $c.attempted -or -not $c.returned -or $c.after.rootExists -or $x.sink.evidence.earlier.marker -cne 'earlier-violation'){throw 'successful early cleanup evidence missing'};$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $x.sink.evidence 'SIMULATED_PASS' $journal.ToArray();if($v.cases.fixtureCleanup.state -cne 'NOT_RUN'){throw 'path-only early cleanup accepted'}}finally{if([IO.Directory]::Exists($f.root)){Remove-PhaseAFixture $f}}
foreach($mode in @('FAIL','NOOP','PARTIAL')){$f=New-TestFixture;try{$x=Run-Early $f $mode 'ACL';$c=$x.sink.evidence.fixtureCleanup;if($x.status -cne 'STAGE3_ACL_REJECTED' -or -not $c.after.rootExists -or ($mode -cin @('FAIL','PARTIAL') -and $c.reason -cne 'CLEANUP_FAILED') -or ($mode -ceq 'NOOP' -and -not $c.returned)){throw 'early failure or original setup reason lost'};$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $x.sink.evidence 'SIMULATED_PASS' $journal.ToArray();if($v.cases.fixtureCleanup.state -cne 'FAIL'){throw 'surviving early fixture not mapped'};$verify=New-PhaseAEvidenceVerifier $journal.ToArray() $v '1' $true $true 'SIMULATED_PASS' @() @{} $x.sink.evidence;if(-not (& $verify 'fixtureCleanup' $v.cases.fixtureCleanup $v)){throw 'early cleanup proof not rechecked'};$bad=$x.sink.evidence.setupFixtureBinding.fixtureId;$x.sink.evidence.setupFixtureBinding.fixtureId='ether-phase-a-store-'+('b'*32);if(& $verify 'fixtureCleanup' $v.cases.fixtureCleanup $v){throw 'wrong fixture proof accepted'};$x.sink.evidence.setupFixtureBinding.fixtureId=$bad;$savedPhase=$c.after.phase;$c.after.phase='BEFORE';if(& $verify 'fixtureCleanup' $v.cases.fixtureCleanup $v){throw 'forged observation accepted'};$c.after.phase=$savedPhase;$savedRole=$c.creation[0].role;$c.creation[0].role='control';if(& $verify 'fixtureCleanup' $v.cases.fixtureCleanup $v){throw 'forged creation sequence accepted'};$c.creation[0].role=$savedRole;if((Get-PhaseAVerdict $v $verify).status -cne 'UNVERIFIED'){throw 'early cleanup failure reached final verdict'}}finally{Remove-PhaseAFixture $f}}
$f=New-TestFixture;try{$x=Run-Early $f 'REMOVE' 'CHILD';if($x.thrown -cne 'STAGE2_CHILD_UNCONFIRMED' -or $x.sink.evidence.fixtureCleanup.attempted -or $x.sink.evidence.fixtureCleanup.reason -cne 'CHILD_UNCONFIRMED' -or -not [IO.Directory]::Exists($f.root)){throw 'unconfirmed child did not retain early fixture'}}finally{Remove-PhaseAFixture $f}
$f=New-TestFixture;try{$records=New-Object 'System.Collections.Generic.List[object]';try{Invoke-PhaseASetupCreation $records 'root' {throw 'root creation failed'}}catch{};$e=@{cleanupVerified=$false};$calls=@{observe=0;cleanup=0};$observe={param($f,$phase) $calls.observe++;Get-PhaseAFixtureCleanupObservation $f $phase 'INJECTED'}.GetNewClosure();$cleanup={param($f) $calls.cleanup++;throw 'must not remove'}.GetNewClosure();Invoke-PhaseAEarlyFixtureCleanup $f $e $records $false $false 'SETUP_FAILED' $observe $cleanup;if($e.fixtureCleanup.reason -cne 'ROOT_UNCONFIRMED' -or $e.fixtureCleanup.attempted -or $calls.observe -ne 1 -or $calls.cleanup -ne 0 -or -not $e.fixtureCleanup.after.rootExists -or $e.fixtureCleanup.creation[0].result -cne 'UNCONFIRMED'){throw 'unconfirmed root creation mishandled'}}finally{Remove-PhaseAFixture $f}
. "$PSScriptRoot/PhaseA.AclInspection.Tests.ps1"
$f=New-TestFixture;try{$prior=$protectedFailure.Clone();$id=[IO.Path]::GetFileName($f.root);$prior.aclEstablishment=@($protectedFailure.aclEstablishment|ForEach-Object {$r=$_.Clone();$r.fixtureId=$id;$r});$prior.aclCorroboration=@($protectedFailure.aclCorroboration|ForEach-Object {$r=$_.Clone();$r.fixtureId=$id;$r});$prior.aclFixtureBinding=$protectedFailure.aclFixtureBinding.Clone();$prior.aclFixtureBinding.fixtureId=$id;$prior.aclFixtureBinding.rootIdentity=$f.root;$x=Run-Early $f 'FAIL' 'ACL' $prior;$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $x.sink.evidence 'SIMULATED_PASS' $journal.ToArray();if($v.cases.aclInspection.state -cne 'FAIL' -or $v.cases.fixtureCleanup.state -cne 'FAIL'){throw 'earlier verified ACL violation discarded'};$check=New-PhaseAEvidenceVerifier $journal.ToArray() $v '1' $true $true 'SIMULATED_PASS' @() @{} $x.sink.evidence;if(-not (& $check 'aclInspection' $v.cases.aclInspection $v)){throw 'earlier ACL violation did not recheck'}}finally{Remove-PhaseAFixture $f}
function New-Item {param($ItemType,$Path) throw 'synthetic root creation failure'}
try {$real=New-PhaseAStage3Backend;$accounts=@(@{sid='S-1-5-21-1'},@{sid='S-1-5-21-2'});$sink=@{};$result=Invoke-PhaseAStage3 $accounts @() $real @{} $sink;if($result.status -cne 'STAGE3_SETUP_FAILED' -or $sink.evidence.fixtureSetupCreation.Count -ne 1 -or $sink.evidence.fixtureSetupCreation[0].result -cne 'UNCONFIRMED' -or $sink.evidence.fixtureCleanup.reason -cne 'ROOT_UNCONFIRMED' -or $sink.evidence.fixtureCleanup.attempted){throw 'actual setup root failure was not retained'}}finally{Remove-Item Function:\New-Item -ErrorAction SilentlyContinue}
Write-Output 'PASS early cleanup failure and manager evidence controls'
